def maximum_unique_subarray_sum(nums):
 seen=set();left=total=answer=0
 for value in nums:
  while value in seen:seen.remove(nums[left]);total-=nums[left];left+=1
  seen.add(value);total+=value;answer=max(answer,total)
 return answer

